// AdhocReplyAddSections contributes this kind's tagged sections to the OPEN
// entity on dml — the BuildEntities body without the entity frame.
// The caller owns BeginEntity / plain setters / CommitEntity.
func AdhocReplyAddSections[
	BoolAttr AdhocReplyBoolAttrI,
	BoolSec AdhocReplyBoolSecI[BoolAttr, Ent],
	TextArrayAttr AdhocReplyTextArrayAttrI,
	TextArraySec AdhocReplyTextArraySecI[TextArrayAttr, Ent],
	StringArrayAttr AdhocReplyStringArrayAttrI,
	StringArraySec AdhocReplyStringArraySecI[StringArrayAttr, Ent],
	U64ArrayAttr AdhocReplyU64ArrayAttrI,
	U64ArraySec AdhocReplyU64ArraySecI[U64ArrayAttr, Ent],
	I64ArrayAttr AdhocReplyI64ArrayAttrI,
	I64ArraySec AdhocReplyI64ArraySecI[I64ArrayAttr, Ent],
	SymbolAttr AdhocReplySymbolAttrI,
	SymbolSec AdhocReplySymbolSecI[SymbolAttr, Ent],
	BlobArrayAttr AdhocReplyBlobArrayAttrI,
	BlobArraySec AdhocReplyBlobArraySecI[BlobArrayAttr, Ent],
	Ent any,
	DML AdhocReplyEntityI[
		BoolAttr, BoolSec,
		TextArrayAttr, TextArraySec,
		StringArrayAttr, StringArraySec,
		U64ArrayAttr, U64ArraySec,
		I64ArrayAttr, I64ArraySec,
		SymbolAttr, SymbolSec,
		BlobArrayAttr, BlobArraySec,
		Ent,
	],
](dml DML, row AdhocReply) (err error) {
	// --- bool. ---
	boolSec := dml.GetSectionBool()
	err = AdhocReplyEmitSectionBool(boolSec, row)
	if err != nil {
		return
	}
	boolSec.EndSection()
	// --- textArray. ---
	textArraySec := dml.GetSectionTextArray()
	err = AdhocReplyEmitSectionTextArray(textArraySec, row)
	if err != nil {
		return
	}
	textArraySec.EndSection()
	// --- stringArray. ---
	stringArraySec := dml.GetSectionStringArray()
	err = AdhocReplyEmitSectionStringArray(stringArraySec, row)
	if err != nil {
		return
	}
	stringArraySec.EndSection()
	// --- u64Array. ---
	u64ArraySec := dml.GetSectionU64Array()
	err = AdhocReplyEmitSectionU64Array(u64ArraySec, row)
	if err != nil {
		return
	}
	u64ArraySec.EndSection()
	// --- i64Array. ---
	i64ArraySec := dml.GetSectionI64Array()
	err = AdhocReplyEmitSectionI64Array(i64ArraySec, row)
	if err != nil {
		return
	}
	i64ArraySec.EndSection()
	// --- symbol. ---
	symbolSec := dml.GetSectionSymbol()
	err = AdhocReplyEmitSectionSymbol(symbolSec, row)
	if err != nil {
		return
	}
	symbolSec.EndSection()
	// --- blobArray. ---
	blobArraySec := dml.GetSectionBlobArray()
	err = AdhocReplyEmitSectionBlobArray(blobArraySec, row)
	if err != nil {
		return
	}
	blobArraySec.EndSection()
	return
}

