// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around AdhocReplyBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// AdhocReplyEntityI.
func (c *AdhocReplyColumns) Marshal(w io.Writer) (err error) {
	ent := adhocReplyPool.Get().(*cbdml.InEntityFacts)
	defer adhocReplyPool.Put(ent)
	ent.SetActiveSections(AdhocReplyActiveSections)
	ent.Builder().SetActiveFields(AdhocReplyActiveFields())
	err = AdhocReplyBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("adhocreply: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("adhocreply: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// adhocReplyReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type adhocReplyReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Bool            *ra.ReadAccessFactsTaggedBool
	TextArray       *ra.ReadAccessFactsTaggedTextArray
	StringArray     *ra.ReadAccessFactsTaggedStringArray
	U64Array        *ra.ReadAccessFactsTaggedU64Array
	I64Array        *ra.ReadAccessFactsTaggedI64Array
	Symbol          *ra.ReadAccessFactsTaggedSymbol
	BlobArray       *ra.ReadAccessFactsTaggedBlobArray
}

func newAdhocReplyReader() *adhocReplyReader {
	return &adhocReplyReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Bool:            ra.NewReadAccessFactsTaggedBool(),
		TextArray:       ra.NewReadAccessFactsTaggedTextArray(),
		StringArray:     ra.NewReadAccessFactsTaggedStringArray(),
		U64Array:        ra.NewReadAccessFactsTaggedU64Array(),
		I64Array:        ra.NewReadAccessFactsTaggedI64Array(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
		BlobArray:       ra.NewReadAccessFactsTaggedBlobArray(),
	}
}

func (r *adhocReplyReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load EntityTimestamp: %w", err)
		return
	}
	err = r.Bool.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load Bool: %w", err)
		return
	}
	err = r.TextArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load TextArray: %w", err)
		return
	}
	err = r.StringArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load StringArray: %w", err)
		return
	}
	err = r.U64Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load U64Array: %w", err)
		return
	}
	err = r.I64Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load I64Array: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load Symbol: %w", err)
		return
	}
	err = r.BlobArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: load BlobArray: %w", err)
		return
	}
	return
}

func (r *adhocReplyReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Bool != nil {
		r.Bool.Release()
	}
	if r.TextArray != nil {
		r.TextArray.Release()
	}
	if r.StringArray != nil {
		r.StringArray.Release()
	}
	if r.U64Array != nil {
		r.U64Array.Release()
	}
	if r.I64Array != nil {
		r.I64Array.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
	if r.BlobArray != nil {
		r.BlobArray.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around AdhocReplyFillFromArrow — the per-row decode lives there.
func (c *AdhocReplyColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newAdhocReplyReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = AdhocReplyFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Bool.Attributes, r.Bool.Memberships,
		r.TextArray.Attributes, r.TextArray.Memberships,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.U64Array.Attributes, r.U64Array.Memberships,
		r.I64Array.Attributes, r.I64Array.Memberships,
		r.Symbol.Attributes, r.Symbol.Memberships,
		r.BlobArray.Attributes, r.BlobArray.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// AdhocReplyCodec is the buscodec.CodecI bridge for AdhocReply. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type AdhocReplyCodec struct{}

var _ buscodec.CodecI = (*AdhocReplyCodec)(nil)

// adhocReplyBusCodec is the package-local singleton wired into buscodec.
var adhocReplyBusCodec = &AdhocReplyCodec{}

func (inst *AdhocReplyCodec) Name() (n string) {
	n = "adhocReply-sparse-cbor"
	return
}

func (inst *AdhocReplyCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=adhocReply"
	return
}

func (inst *AdhocReplyCodec) Encode(v any) (b []byte, err error) {
	var row AdhocReply
	switch x := v.(type) {
	case AdhocReply:
		row = x
	case *AdhocReply:
		if x == nil {
			err = eh.Errorf("adhocreply: Encode nil *AdhocReply")
			return
		}
		row = *x
	default:
		err = eh.Errorf("adhocreply: Encode requires AdhocReply or *AdhocReply, got %T", v)
		return
	}
	cols := &AdhocReplyColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("adhocreply: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *AdhocReplyCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*AdhocReply)
	if !ok {
		err = eh.Errorf("adhocreply: Decode requires *AdhocReply, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocreply: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("adhocreply: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("adhocreply: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &AdhocReplyColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("adhocreply: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("adhocreply: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
